// The text of the HyperFrames project's generated files that the whole project
// (render/timing.mjs) and each chapter's project (render/chapter-project.mjs)
// share, so a chapter's is the whole's with its own clock.
import { NO_WORD } from "./anchors.mjs";
import { HEIGHT, WIDTH, esc } from "./root.mjs";

export const r3 = (n) => +n.toFixed(3);

// `words` with `by` seconds added to each time.
export const shift = (words, by) =>
  words.map((w) => ({
    text: w.text,
    start: r3(by + w.start),
    end: r3(by + w.end),
  }));

// The `scenes` of window.TIMING for the timeline's `scenes`: each scene's
// `start` as `startOf` gives it, its duration and its words local to it, read
// from the voice stage's `voice`.
export const timingScenes = (scenes, voice, startOf) =>
  Object.fromEntries(
    scenes.map((s) => [
      s.id,
      {
        start: startOf(s),
        duration: s.duration,
        words: shift(voice.scenes.find((v) => v.id === s.id).words, 0),
      },
    ]),
  );

// timing.js: window.TIMING, `scenes` keyed by id with the scene's `start` in
// the project's video, its `duration` and `words` local to the scene, and
// window.at(scene, word, nth), the start of the nth matching word, which scene
// scripts cue to.
export const timingJs = (
  total,
  scenes,
) => `// Generated by the creative-video skill: do not edit.
window.TIMING = ${JSON.stringify({ total, scenes })};
window.at = (scene, word, nth = 1) => {
  const norm = (s) => s.toLowerCase().replace(/[^\\p{L}\\p{N}]/gu, "");
  const hits = (window.TIMING.scenes[scene]?.words ?? []).filter(
    (w) => norm(w.text) === norm(word),
  );
  if (!hits[nth - 1])
    throw new Error(\`${NO_WORD} "\${word}" (\${nth}) in scene \${scene}\`);
  return hits[nth - 1].start;
};
`;

// compositions/captions.html: `cues` as HyperFrames cue clips, a cue's
// role's name in its own span before its words.
export function captionsHtml(cues) {
  const cueDivs = cues
    .map(
      (c, i) =>
        `    <div class="cue clip" data-start="${c.start}" data-duration="${(c.end - c.start).toFixed(3)}" id="cue-${i + 1}">${c.who ? `<span class="who">${esc(c.who)}:</span> ` : ""}${c.tokens
          .map((t) => `<span class="w">${esc(t.text)}</span>`)
          .join(" ")}</div>`,
    )
    .join("\n");
  return `<template>
  <style>
    #root {
      position: absolute;
      inset: 0;
    }
    .cue {
      position: absolute;
      left: 160px;
      right: 160px;
      bottom: 96px;
      text-align: center;
      font: 700 44px Inter, sans-serif;
      color: #fff;
      text-shadow: 0 2px 8px rgba(0, 0, 0, 0.85);
    }
  </style>
  <div id="root" data-composition-id="captions" data-width="${WIDTH}" data-height="${HEIGHT}">
${cueDivs}
  </div>
  <script>
    window.__timelines["captions"] = gsap.timeline({ paused: true });
  </script>
</template>
`;
}
